% mathsmap-diagram-colours {"version":1,"kind":"geometry","base":[],"semantic":[],"reference":"source page 15, p15-q18-diagram"}
\usetikzlibrary{calc,angles}
\begin{tikzpicture}[x={(0.8cm,-0.033333cm)},y={(0.067358cm,0.336788cm)},z={(-0.002311cm,0.737296cm)},draw=black,text=black,line width=0.8pt,every node/.style={font=\fontsize{10}{12}\selectfont}]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
% Explicit solid vertices in cm: C=(0,0,0), A=(6,0,0), B=(3,3sqrt(3),0), O=(3,sqrt(3),sqrt(52)).
% Faces: OCA, OAB, OBC, ABC. Object-to-viewer direction is proportional to (0.05045,-0.58976,0.27170).
% Only OCA faces the viewer; OC, OA, CA are silhouette edges. OB, BC, BA are obscured solid edges.
\coordinate (C) at (0,0,0);
\coordinate (A) at (6,0,0);
\coordinate (B) at (3,{3*sqrt(3)},0);
\coordinate (O) at (3,{sqrt(3)},{sqrt(52)});
\coordinate (X) at ($(C)!0.28125!(O)$);
\draw (C)--(O)--(A)--cycle;
\draw[dashed] (O)--(B)--(C) (B)--(A);
% Construction segments are separate from solid edges.
\draw (X)--(A) (X)--(B);
% Equal base-edge ticks, derived from each projected segment.
\foreach \L/\R in {C/A,A/B,B/C}{
  \coordinate (M) at ($(\L)!0.5!(\R)$);
  \draw[line width=0.4pt] ($(M)!2.5pt!90:(\R)$)--($(M)!2.5pt!-90:(\R)$);
}
% Equal slant-edge double ticks.
\foreach \L/\R in {O/A,O/B,O/C}{
  \coordinate (M) at ($(\L)!0.5!(\R)$);
  \coordinate (T) at ($(M)!1.4pt!(\R)$);
  \coordinate (U) at ($(M)!1.4pt!(\L)$);
  \draw[line width=0.4pt] ($(T)!2.5pt!90:(\R)$)--($(T)!2.5pt!-90:(\R)$);
  \draw[line width=0.4pt] ($(U)!2.5pt!90:(\R)$)--($(U)!2.5pt!-90:(\R)$);
}
% Project the two actual perpendicular corner squares at X.
\coordinate (XOmark) at ($(X)!0.035!(O)$);
\coordinate (XAmark) at ($(X)!0.045!(A)$);
\coordinate (XBmark) at ($(X)!0.065!(B)$);
\draw[line width=0.4pt] (XOmark)--($(XOmark)+(XAmark)-(X)$)--(XAmark);
\draw[line width=0.4pt] (XOmark)--($(XOmark)+(XBmark)-(X)$)--(XBmark);
\path (O)--(A) node[midway,right=5pt] {$8\text{ cm}$};
\path (C)--(A) node[midway,below=5pt] {$6\text{ cm}$};
\fill (O) circle[radius=1.2pt] node[above=3pt] {$O$};
\fill (C) circle[radius=1.2pt] node[below left=3pt] {$C$};
\fill (A) circle[radius=1.2pt] node[below right=3pt] {$A$};
\fill (B) circle[radius=1.2pt] node[above right=3pt] {$B$};
\fill (X) circle[radius=1pt] node[left=4pt] {$X$};
\end{tikzpicture}
